  dlIncome: { es: 'Impuesto sobre la renta ({what})', en: 'Income tax ({what})', pt: 'Imposto sobre o rendimento ({what})', fr: 'Impôt sur le revenu ({what})', de: 'Einkommensteuer ({what})', it: 'Imposta sul reddito ({what})' },
