  moveDone: { es: 'Ya estás con las reglas de {country}.', en: 'You are on {country}’s rules now.', pt: 'Já estás com as regras de {country}.', fr: 'Vous suivez désormais les règles de {country}.', de: 'Jetzt gelten die Regeln von {country}.', it: 'Ora segui le regole di {country}.' },
  moveSameCountry: { es: 'Ese es tu país actual.', en: 'That is your current country.', pt: 'Esse é o teu país atual.', fr: 'C’est votre pays actuel.', de: 'Das ist dein aktuelles Land.', it: 'È il tuo paese attuale.' },
