  expRead: { es: 'He leído el documento: revisa los datos antes de guardarlo.', en: 'I read the document: check the details before saving.', pt: 'Li o documento: revê os dados antes de guardar.', fr: 'J’ai lu le document : vérifiez les données avant d’enregistrer.', de: 'Ich habe das Dokument gelesen: Prüfe die Angaben vor dem Speichern.', it: 'Ho letto il documento: controlla i dati prima di salvare.' },
