  shopCreating: { es: 'Creando tus direcciones de cobro', en: 'Making your payment addresses', pt: 'A criar os teus endereços de pagamento', fr: 'Création de vos adresses de paiement', de: 'Zahlungsadressen werden erstellt', it: 'Creazione degli indirizzi di pagamento' },
  shopStep: { es: 'Dirección para IVA {pct} % ({i}): confirma con tu wallet', en: 'Address for {pct}% VAT ({i}): confirm in your wallet', pt: 'Endereço para IVA {pct} % ({i}): confirma na carteira', fr: 'Adresse pour la TVA {pct} % ({i}) : confirmez dans votre wallet', de: 'Adresse für {pct} % USt. ({i}): im Wallet bestätigen', it: 'Indirizzo per IVA {pct}% ({i}): conferma nel wallet' },
  shopConfig: { es: 'Configuración para tu tienda o tu API', en: 'Settings for your shop or your API', pt: 'Configuração para a tua loja ou API', fr: 'Configuration pour votre boutique ou votre API', de: 'Einstellungen für deinen Shop oder deine API', it: 'Configurazione per il tuo negozio o la tua API' },
  shopConfigSub: { es: 'Pégala en WooCommerce (Ajustes → Pagos → Kyros), en el servidor de Kyros para Shopify o en tu servidor x402. No contiene ninguna clave: solo tus direcciones de cobro.', en: 'Paste it into WooCommerce (Settings → Payments → Kyros), the Kyros for Shopify server or your x402 server. It holds no key: only your payment addresses.', pt: 'Cola-a no WooCommerce (Definições → Pagamentos → Kyros), no servidor Kyros para Shopify ou no teu servidor x402. Não contém nenhuma chave: só os teus endereços de pagamento.', fr: 'Collez-la dans WooCommerce (Réglages → Paiements → Kyros), le serveur Kyros pour Shopify ou votre serveur x402. Elle ne contient aucune clé : seulement vos adresses.', de: 'Füge sie in WooCommerce ein (Einstellungen → Zahlungen → Kyros), in den Kyros-Server für Shopify oder deinen x402-Server. Sie enthält keinen Schlüssel, nur deine Adressen.', it: 'Incollala in WooCommerce (Impostazioni → Pagamenti → Kyros), nel server Kyros per Shopify o nel tuo server x402. Non contiene chiavi: solo i tuoi indirizzi.' },
